import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');

const { fontFamily: playfairFamily } = loadPlayfair();



export type ChessboardProps = Record<string, any>;

const PawnIcon: React.FC<{ color: string; id: string }> = ({ color, id }) => {
  const gradId = `grad-${id}`;
  return (
    <svg 
      viewBox="0 0 100 200" 
      width="100%" 
      height="100%" 
      style={{ filter: "drop-shadow(0px 8px 12px rgba(0,0,0,0.5))" }}
    >
      <defs>
        <linearGradient id={gradId} x1="0%" y1="0%" x2="100%" y2="0%">
          <stop offset="0%" stopColor={color} />
          <stop offset="20%" stopColor="#ffffff" stopOpacity={color === "#ffffff" ? 0.9 : 0.2} />
          <stop offset="60%" stopColor={color} />
          <stop offset="100%" stopColor="#000000" stopOpacity={0.6} />
        </linearGradient>
      </defs>
      
      {/* Base */}
      <path d="M 15 170 Q 15 150 35 140 L 65 140 Q 85 150 85 170 L 95 190 A 5 5 0 0 1 90 200 L 10 200 A 5 5 0 0 1 5 190 Z" fill={`url(#${gradId})`} />
      
      {/* Body */}
      <path d="M 35 140 C 45 100 45 85 45 85 L 55 85 C 55 85 55 100 65 140 Z" fill={`url(#${gradId})`} />
      
      {/* Collar */}
      <rect x="35" y="75" width="30" height="10" rx="4" fill={`url(#${gradId})`} />
      
      {/* Head */}
      <circle cx="50" cy="45" r="28" fill={`url(#${gradId})`} />
      
      {/* Glossy specular highlight */}
      <path d="M 30 175 Q 30 160 40 150 L 45 150 Q 32 160 35 185 Z" fill="rgba(255,255,255,0.3)" />
      <circle cx="42" cy="35" r="8" fill="rgba(255,255,255,0.5)" />
    </svg>
  );
};

const ChessboardAnimation: React.FC<ChessboardProps> = ({
  backgroundColor = "#111827",
  transparentBackground = false,
  durationInSeconds = 4,
  boardDarkColor = "#769656",
  boardLightColor = "#eeeed2",
  boardBorderColor = "#2c1e16",
  whitePawnColor = "#ffffff",
  blackPawnColor = "#2b2b2b",
  highlightColor = "#f5f682",
  startAngleZ = 45,
  endAngleZ = 15,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Board dimensions
  const boardSize = Math.min(width, height) * 0.75;
  const cellSize = boardSize / 8;
  const pawnWidth = cellSize * 0.7;
  const pawnHeight = pawnWidth * 2;
  const shadowWidth = cellSize * 0.7;
  const shadowHeight = cellSize * 0.3;

  // Camera & Constant Visibility
  const boardScale = 1;
  const boardOpacity = 1;
  const boardRotateX = 60;
  
  const boardRotateZ = interpolate(frame, [0, durationInFrames], [startAngleZ, endAngleZ], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Pawn Jump Animation (e2 to e4)
  const moveProgress = spring({
    frame: frame - 35,
    fps,
    config: { damping: 20, stiffness: 80 }
  });

  const clampedProgress = Math.max(0, Math.min(1, moveProgress));

  // Coordinates for animated pawn (col 4, row 6 -> col 4, row 4)
  const startCol = 4, startRow = 6;
  const endCol = 4, endRow = 4;
  
  const startX = startCol * cellSize;
  const startY = startRow * cellSize;
  const endX = endCol * cellSize;
  const endY = endRow * cellSize;

  const currentX = interpolate(clampedProgress, [0, 1], [startX, endX]);
  const currentY = interpolate(clampedProgress, [0, 1], [startY, endY]);
  
  // Parabolic Z-axis jump
  const rawZ = (1 - Math.pow((clampedProgress - 0.5) * 2, 2)) * (cellSize * 1.5);
  const currentZ = Math.max(0, rawZ);

  // Layout centering formulas
  const getPawnLeft = (x: number) => x + cellSize / 2 - pawnWidth / 2;
  const getPawnTop = (y: number) => y + cellSize / 2 - pawnHeight;
  const getShadowLeft = (x: number) => x + cellSize / 2 - shadowWidth / 2;
  const getShadowTop = (y: number) => y + cellSize / 2 - shadowHeight / 2;

  // Static initial pawns (excluding the animated e2 pawn)
  const staticPawns = [
    ...Array.from({ length: 8 }).map((_, i) => ({ id: `bp-${i}`, col: i, row: 1, color: blackPawnColor })),
    ...Array.from({ length: 8 }).map((_, i) => ({ id: `wp-${i}`, col: i, row: 6, color: whitePawnColor })),
  ].filter(p => !(p.col === 4 && p.row === 6));

  const files = ["a", "b", "c", "d", "e", "f", "g", "h"];
  const ranks = ["8", "7", "6", "5", "4", "3", "2", "1"];

  const highlightOpacity = interpolate(clampedProgress, [0, 0.1], [0, 0.6]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, perspective: "1500px", transition: "none" }}>
      <div style={{
        width: "100%",
        height: "100%",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        transformStyle: "preserve-3d",
      }}>
        {/* The Board Container */}
        <div style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          marginLeft: -boardSize / 2,
          marginTop: -boardSize / 2,
          width: boardSize,
          height: boardSize,
          transformStyle: "preserve-3d",
          transform: `scale(${boardScale}) rotateX(${boardRotateX}deg) rotateZ(${boardRotateZ}deg)`,
          opacity: boardOpacity,
          transition: "none",
        }}>
          {/* Wooden Border & Labels */}
          <div style={{
            position: "absolute",
            inset: -30,
            backgroundColor: boardBorderColor,
            borderRadius: 12,
            boxShadow: "0 40px 80px rgba(0,0,0,0.7), inset 0 4px 10px rgba(0,0,0,0.6)",
            transform: "translateZ(-2px)",
            transformStyle: "preserve-3d",
          }}>
            {files.map((file, i) => (
              <div key={`file-${file}`} style={{
                position: "absolute",
                left: 30 + i * cellSize,
                bottom: 5,
                width: cellSize,
                textAlign: "center",
                color: boardLightColor,
                fontSize: 14,
                fontWeight: "bold",
                fontFamily: playfairFamily,
                opacity: 0.8,
              }}>
                {file}
              </div>
            ))}
            {ranks.map((rank, i) => (
              <div key={`rank-${rank}`} style={{
                position: "absolute",
                top: 30 + i * cellSize,
                left: 10,
                height: cellSize,
                display: "flex",
                alignItems: "center",
                color: boardLightColor,
                fontSize: 14,
                fontWeight: "bold",
                fontFamily: playfairFamily,
                opacity: 0.8,
              }}>
                {rank}
              </div>
            ))}
          </div>

          {/* Grid Squares */}
          <div style={{
            position: "absolute",
            inset: 0,
            display: "grid",
            gridTemplateColumns: "repeat(8, 1fr)",
            gridTemplateRows: "repeat(8, 1fr)",
            border: `4px solid #1a110d`,
            borderRadius: 6,
            overflow: "hidden",
            transformStyle: "preserve-3d",
          }}>
            {Array.from({ length: 64 }).map((_, i) => {
              const col = i % 8;
              const row = Math.floor(i / 8);
              const isDark = (col + row) % 2 === 1;
              return (
                <div 
                  key={`cell-${i}`} 
                  style={{ backgroundColor: isDark ? boardDarkColor : boardLightColor }} 
                />
              );
            })}
          </div>

          {/* Highlights for start and end squares */}
          <div style={{
            position: "absolute",
            left: startCol * cellSize,
            top: startRow * cellSize,
            width: cellSize,
            height: cellSize,
            backgroundColor: highlightColor,
            opacity: highlightOpacity,
          }} />
          <div style={{
            position: "absolute",
            left: endCol * cellSize,
            top: endRow * cellSize,
            width: cellSize,
            height: cellSize,
            backgroundColor: highlightColor,
            opacity: highlightOpacity,
          }} />

          {/* Static Pawns */}
          {staticPawns.map(p => {
            const pX = p.col * cellSize;
            const pY = p.row * cellSize;
            return (
              <React.Fragment key={p.id}>
                {/* Static Shadow */}
                <div style={{
                  position: "absolute",
                  left: getShadowLeft(pX),
                  top: getShadowTop(pY),
                  width: shadowWidth,
                  height: shadowHeight,
                  backgroundColor: "rgba(0,0,0,0.5)",
                  borderRadius: "50%",
                  filter: "blur(4px)",
                  transform: "translateZ(1px)",
                }} />
                {/* Static Piece */}
                <div style={{
                  position: "absolute",
                  left: getPawnLeft(pX),
                  top: getPawnTop(pY),
                  width: pawnWidth,
                  height: pawnHeight,
                  transformOrigin: "bottom center",
                  transformStyle: "preserve-3d",
                  transform: `translateZ(0px) rotateZ(${-boardRotateZ}deg) rotateX(-90deg)`,
                }}>
                  <PawnIcon color={p.color} id={p.id} />
                </div>
              </React.Fragment>
            );
          })}

          {/* Animated Pawn Shadow */}
          <div style={{
            position: "absolute",
            left: getShadowLeft(currentX),
            top: getShadowTop(currentY),
            width: shadowWidth,
            height: shadowHeight,
            backgroundColor: "rgba(0,0,0,0.5)",
            borderRadius: "50%",
            filter: "blur(4px)",
            opacity: interpolate(clampedProgress, [0, 0.5, 1], [1, 0.3, 1]),
            transform: `translateZ(1px) scale(${interpolate(clampedProgress, [0, 0.5, 1], [1, 0.6, 1])})`,
          }} />

          {/* Animated Pawn (e2 -> e4) */}
          <div style={{
            position: "absolute",
            left: getPawnLeft(currentX),
            top: getPawnTop(currentY),
            width: pawnWidth,
            height: pawnHeight,
            transformOrigin: "bottom center",
            transformStyle: "preserve-3d",
            transform: `translateZ(${currentZ}px) rotateZ(${-boardRotateZ}deg) rotateX(-90deg)`,
          }}>
            <PawnIcon color={whitePawnColor} id="animated-pawn" />
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ChessboardAnimation;